) as v (code, name, canton, provincia, geojson);

-- Parents first: zones.parent_code references zones.code.
with g as (
  select left(code, 1) as code,
         min(provincia) as name,
         extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_union(geom)), 3)) as geom
    from zone_seed
   group by 1
)
insert into public.zones (code, kind, name, parent_code, centroid, area_km2, boundary, source)
select code, 'provincia', name, null,
       extensions.st_pointonsurface(geom)::extensions.geography,
       round((extensions.st_area(geom::extensions.geography) / 1e6)::numeric, 3),
       geom::extensions.geography,
       'osm-2026-09-19'
  from g
on conflict (code) do update
   set kind = excluded.kind, name = excluded.name, parent_code = excluded.parent_code,
       centroid = excluded.centroid, area_km2 = excluded.area_km2,
       boundary = excluded.boundary, source = excluded.source, updated_at = now();

with g as (
  select left(code, 3) as code,
         min(canton) as name,
         extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_union(geom)), 3)) as geom
    from zone_seed
   group by 1
)
insert into public.zones (code, kind, name, parent_code, centroid, area_km2, boundary, source)
select code, 'canton', name, left(code, 1),
       extensions.st_pointonsurface(geom)::extensions.geography,
       round((extensions.st_area(geom::extensions.geography) / 1e6)::numeric, 3),
       geom::extensions.geography,
       'osm-2026-09-19'
  from g
on conflict (code) do update
   set kind = excluded.kind, name = excluded.name, parent_code = excluded.parent_code,
       centroid = excluded.centroid, area_km2 = excluded.area_km2,
       boundary = excluded.boundary, source = excluded.source, updated_at = now();

-- A distrito is its own row, except where a part rejoins it (see above).
with g as (
  select left(code, 5) as code,
         min(name) as name,
         extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_union(geom)), 3)) as geom
    from zone_seed
   group by 1
)
insert into public.zones (code, kind, name, parent_code, centroid, area_km2, boundary, source)
select code, 'distrito', name, left(code, 3),
       extensions.st_pointonsurface(geom)::extensions.geography,
       round((extensions.st_area(geom::extensions.geography) / 1e6)::numeric, 3),
       geom::extensions.geography,
       'osm-2026-09-19'
  from g
on conflict (code) do update
   set kind = excluded.kind, name = excluded.name, parent_code = excluded.parent_code,
       centroid = excluded.centroid, area_km2 = excluded.area_km2,
       boundary = excluded.boundary, source = excluded.source, updated_at = now();

-- Venues created before the grid existed resolved against an empty table.
-- 0015 made the trigger place any row that has no code yet.
update public.locations set geog = geog where district_code is null;

do $$
declare
  v_p integer;
  v_c integer;
  v_d integer;
begin
  select count(*) filter (where kind = 'provincia'),
         count(*) filter (where kind = 'canton'),
         count(*) filter (where kind = 'distrito')
    into v_p, v_c, v_d
    from public.zones
   where source = 'osm-2026-09-19';
  if (v_p, v_c, v_d) <> (7, 84, 494) then
    raise exception 'zone seed wrote % / % / %, expected 7 / 84 / 494', v_p, v_c, v_d;
  end if;
end $$;

drop table zone_seed;
